static const uint8_t k_alpha[26][7]={{0x0e,0x11,0x11,0x1f,0x11,0x11,0x11},{0x1e,0x11,0x11,0x1e,0x11,0x11,0x1e},{0x0f,0x10,0x10,0x10,0x10,0x10,0x0f},{0x1e,0x11,0x11,0x11,0x11,0x11,0x1e},{0x1f,0x10,0x10,0x1e,0x10,0x10,0x1f},{0x1f,0x10,0x10,0x1e,0x10,0x10,0x10},{0x0f,0x10,0x10,0x17,0x11,0x11,0x0f},{0x11,0x11,0x11,0x1f,0x11,0x11,0x11},{0x1f,0x04,0x04,0x04,0x04,0x04,0x1f},{0x07,0x02,0x02,0x02,0x12,0x12,0x0c},{0x11,0x12,0x14,0x18,0x14,0x12,0x11},{0x10,0x10,0x10,0x10,0x10,0x10,0x1f},{0x11,0x1b,0x15,0x15,0x11,0x11,0x11},{0x11,0x19,0x15,0x13,0x11,0x11,0x11},{0x0e,0x11,0x11,0x11,0x11,0x11,0x0e},{0x1e,0x11,0x11,0x1e,0x10,0x10,0x10},{0x0e,0x11,0x11,0x11,0x15,0x12,0x0d},{0x1e,0x11,0x11,0x1e,0x14,0x12,0x11},{0x0f,0x10,0x10,0x0e,0x01,0x01,0x1e},{0x1f,0x04,0x04,0x04,0x04,0x04,0x04},{0x11,0x11,0x11,0x11,0x11,0x11,0x0e},{0x11,0x11,0x11,0x11,0x11,0x0a,0x04},{0x11,0x11,0x11,0x15,0x15,0x15,0x0a},{0x11,0x11,0x0a,0x04,0x0a,0x11,0x11},{0x11,0x11,0x0a,0x04,0x04,0x04,0x04},{0x1f,0x01,0x02,0x04,0x08,0x10,0x1f}};
static const uint8_t k_digit[10][7]={{0x0e,0x11,0x13,0x15,0x19,0x11,0x0e},{0x04,0x0c,0x04,0x04,0x04,0x04,0x0e},{0x0e,0x11,0x01,0x02,0x04,0x08,0x1f},{0x1e,0x01,0x01,0x0e,0x01,0x01,0x1e},{0x02,0x06,0x0a,0x12,0x1f,0x02,0x02},{0x1f,0x10,0x10,0x1e,0x01,0x01,0x1e},{0x0e,0x10,0x10,0x1e,0x11,0x11,0x0e},{0x1f,0x01,0x02,0x04,0x08,0x08,0x08},{0x0e,0x11,0x11,0x0e,0x11,0x11,0x0e},{0x0e,0x11,0x11,0x0f,0x01,0x01,0x0e}};
static uint8_t glyph_row(char c,uint8_t r){if(r>=7u)return 0u;if(c>='A'&&c<='Z')return k_alpha[(uint8_t)(c-'A')][r];if(c>='0'&&c<='9')return k_digit[(uint8_t)(c-'0')][r];switch(c){case '-':return r==3u?0x1fu:0u;case ':':return(r==2u||r==5u)?0x04u:0u;case '.':return r==6u?0x04u:0u;case '=':return(r==2u||r==4u)?0x1fu:0u;case '/':return r<=4u?(uint8_t)(1u<<(4u-r)):0u;case '\\':return r<=4u?(uint8_t)(1u<<r):0u;case '>':{static const uint8_t x[7]={0x10,0x08,0x04,0x02,0x04,0x08,0x10};return x[r];}case '<':{static const uint8_t x[7]={0x01,0x02,0x04,0x08,0x04,0x02,0x01};return x[r];}case '?':{static const uint8_t x[7]={0x0e,0x11,0x01,0x02,0x04,0x00,0x04};return x[r];}case '!':return(r<5u||r==6u)?0x04u:0u;default:return 0u;}}
void blu2usb_ui_frame_reset(blu2usb_ui_frame_t *f,bool learn,uint8_t hint){if(f==NULL)return;if(hint>BLU2USB_RENDERER_TEXT_ROWS)hint=BLU2USB_RENDERER_TEXT_ROWS;f->learn_background=learn;f->hint_start_row=hint;for(size_t r=0;r<BLU2USB_RENDERER_TEXT_ROWS;++r)for(size_t c=0;c<BLU2USB_RENDERER_TEXT_COLS;++c){f->cells[r][c].character=' ';f->cells[r][c].tone=BLU2USB_UI_TONE_ACTIONABLE;}}
bool blu2usb_ui_frame_set_text(blu2usb_ui_frame_t *f,uint8_t r,uint8_t c,const char *t,blu2usb_ui_tone_t tone){if(f==NULL||t==NULL||r>=BLU2USB_RENDERER_TEXT_ROWS||c>=BLU2USB_RENDERER_TEXT_COLS)return false;size_t i=0;while(t[i]!='\0'&&(size_t)c+i<BLU2USB_RENDERER_TEXT_COLS){f->cells[r][(size_t)c+i].character=t[i];f->cells[r][(size_t)c+i].tone=tone;++i;}return t[i]=='\0';}
bool blu2usb_ui_frame_set_tone_span(blu2usb_ui_frame_t *f,uint8_t r,uint8_t c,uint8_t len,blu2usb_ui_tone_t tone){if(f==NULL||r>=9u||c>=21u||(size_t)c+len>21u)return false;for(size_t i=0;i<len;++i)f->cells[r][(size_t)c+i].tone=tone;return true;}
static bool starts_with(const char *t,const char *p){return t!=NULL&&p!=NULL&&strncmp(t,p,strlen(p))==0;}
static uint8_t first_hint_row(const blu2usb_screen_template_t *s){for(uint8_t r=1;r<9u;++r){const char *t=s->rows[r];if(starts_with(t,"JOY ")||starts_with(t,"KEY ")||starts_with(t,"ANY KEY"))return r;}return 9u;}
static int selected_row(const blu2usb_ux_model_t *ux){switch(ux->screen){case BLU2USB_SCREEN_HOME:case BLU2USB_SCREEN_MOUSE_OPTIONS:case BLU2USB_SCREEN_OTHER_OPTIONS:case BLU2USB_SCREEN_EDIT_CUSTOM:case BLU2USB_SCREEN_LEFT_WILL_BECOME:case BLU2USB_SCREEN_RIGHT_WILL_BECOME:case BLU2USB_SCREEN_MIDDLE_WILL_BECOME:case BLU2USB_SCREEN_FORWARD_WILL_BECOME:case BLU2USB_SCREEN_BACKWARD_WILL_BECOME:case BLU2USB_SCREEN_SAVED_DEVICES:return(int)(1u+ux->selection);case BLU2USB_SCREEN_DEVICE_DETAILS_MOUSE:return 5;case BLU2USB_SCREEN_DEVICE_DETAILS_KEYBOARD:case BLU2USB_SCREEN_DEVICE_DETAILS_COMPOSITE:return 4;default:return -1;}}
static void set_row_tone(blu2usb_ui_frame_t *f,uint8_t r,blu2usb_ui_tone_t tone){for(uint8_t c=0;c<21u;++c)if(f->cells[r][c].character!=' ')f->cells[r][c].tone=tone;}
static void emphasize_row(blu2usb_ui_frame_t *f,uint8_t r){set_row_tone(f,r,BLU2USB_UI_TONE_EMPHASIZED);}
static bool success(blu2usb_screen_id_t s){return s==BLU2USB_SCREEN_PASSTHROUGH_APPLIED||s==BLU2USB_SCREEN_DEFAULT_APPLIED||s==BLU2USB_SCREEN_ESCAPE_APPLIED;}
static uint8_t active_profile_row(const blu2usb_ux_model_t *ux){if(ux->screen!=BLU2USB_SCREEN_MOUSE_OPTIONS)return 0u;switch(ux->active_profile){case BLU2USB_MOUSE_PROFILE_PASSTHROUGH:return 2u;case BLU2USB_MOUSE_PROFILE_DEFAULT_REMAP:return 3u;case BLU2USB_MOUSE_PROFILE_ESCAPE_REMAP:return 4u;case BLU2USB_MOUSE_PROFILE_CUSTOM_REMAP:return 5u;default:return 0u;}}
static bool row_has_control(const char *row,blu2usb_control_t control){if(row==NULL)return false;switch(control){case BLU2USB_CONTROL_JOY_UP:return strstr(row,"JOY UP")!=NULL;case BLU2USB_CONTROL_JOY_DOWN:return strstr(row,"JOY DOWN")!=NULL;case BLU2USB_CONTROL_JOY_LEFT:return strstr(row,"JOY LEFT")!=NULL||strstr(row,"RIGHT\\LEFT")!=NULL;case BLU2USB_CONTROL_JOY_RIGHT:return strstr(row,"JOY RIGHT")!=NULL;case BLU2USB_CONTROL_JOY_PRESS:return strstr(row,"JOY PRESS")!=NULL;case BLU2USB_CONTROL_KEY_A:return strstr(row,"KEY A")!=NULL;case BLU2USB_CONTROL_KEY_B:return strstr(row,"KEY B")!=NULL;case BLU2USB_CONTROL_KEY_X:return strstr(row,"KEY X")!=NULL||strstr(row,"KEY C")!=NULL;case BLU2USB_CONTROL_KEY_Y:return strstr(row,"KEY Y")!=NULL;default:return false;}}
static void project_learn_pressed(const blu2usb_ux_model_t *ux,blu2usb_ui_frame_t *f){if(blu2usb_interaction_is_pressed(&ux->interaction,BLU2USB_CONTROL_JOY_UP))(void)blu2usb_ui_frame_set_tone_span(f,1,6,6,BLU2USB_UI_TONE_EMPHASIZED);if(blu2usb_interaction_is_pressed(&ux->interaction,BLU2USB_CONTROL_JOY_LEFT)){(void)blu2usb_ui_frame_set_tone_span(f,2,0,3,BLU2USB_UI_TONE_EMPHASIZED);(void)blu2usb_ui_frame_set_tone_span(f,3,0,4,BLU2USB_UI_TONE_EMPHASIZED);}if(blu2usb_interaction_is_pressed(&ux->interaction,BLU2USB_CONTROL_JOY_PRESS)){(void)blu2usb_ui_frame_set_tone_span(f,2,7,3,BLU2USB_UI_TONE_EMPHASIZED);(void)blu2usb_ui_frame_set_tone_span(f,3,6,5,BLU2USB_UI_TONE_EMPHASIZED);}if(blu2usb_interaction_is_pressed(&ux->interaction,BLU2USB_CONTROL_JOY_RIGHT)){(void)blu2usb_ui_frame_set_tone_span(f,2,14,3,BLU2USB_UI_TONE_EMPHASIZED);(void)blu2usb_ui_frame_set_tone_span(f,3,13,5,BLU2USB_UI_TONE_EMPHASIZED);}if(blu2usb_interaction_is_pressed(&ux->interaction,BLU2USB_CONTROL_JOY_DOWN))(void)blu2usb_ui_frame_set_tone_span(f,4,5,8,BLU2USB_UI_TONE_EMPHASIZED);if(blu2usb_interaction_is_pressed(&ux->interaction,BLU2USB_CONTROL_KEY_A))(void)blu2usb_ui_frame_set_tone_span(f,5,15,5,BLU2USB_UI_TONE_EMPHASIZED);if(blu2usb_interaction_is_pressed(&ux->interaction,BLU2USB_CONTROL_KEY_B))(void)blu2usb_ui_frame_set_tone_span(f,6,15,5,BLU2USB_UI_TONE_EMPHASIZED);if(blu2usb_interaction_is_pressed(&ux->interaction,BLU2USB_CONTROL_KEY_X))(void)blu2usb_ui_frame_set_tone_span(f,7,15,5,BLU2USB_UI_TONE_EMPHASIZED);if(blu2usb_interaction_is_pressed(&ux->interaction,BLU2USB_CONTROL_KEY_Y)){(void)blu2usb_ui_frame_set_tone_span(f,6,0,11,BLU2USB_UI_TONE_EMPHASIZED);(void)blu2usb_ui_frame_set_tone_span(f,7,1,10,BLU2USB_UI_TONE_EMPHASIZED);(void)blu2usb_ui_frame_set_tone_span(f,8,2,18,BLU2USB_UI_TONE_EMPHASIZED);}}
void blu2usb_ui_project(const blu2usb_ux_model_t *ux,blu2usb_ui_frame_t *f){if(ux==NULL||f==NULL)return;const blu2usb_screen_template_t *s=blu2usb_ux_screen_template(ux->screen);if(s==NULL)return;const bool learn=ux->screen==BLU2USB_SCREEN_LEARN_KEYS;const bool sf=success(ux->screen);const bool cf=ux->screen==BLU2USB_SCREEN_EDIT_CUSTOM&&ux->active_profile==BLU2USB_MOUSE_PROFILE_CUSTOM_REMAP&&!ux->custom_dirty;const uint8_t hint=learn?9u:first_hint_row(s);blu2usb_ui_frame_reset(f,learn,hint);for(uint8_t r=0;r<9u;++r){const char *t=s->rows[r]!=NULL?s->rows[r]:"";if(cf&&r==8u)t="";blu2usb_ui_tone_t tone;if(r==0)tone=BLU2USB_UI_TONE_TITLE;else if(sf&&r<hint&&t[0]!='\0')tone=BLU2USB_UI_TONE_CURRENT;else if(cf&&r>=1u&&r<=5u)tone=BLU2USB_UI_TONE_CURRENT;else if(learn||r>=hint||t[0]==' ')tone=BLU2USB_UI_TONE_ACTIONABLE;else tone=BLU2USB_UI_TONE_STATIC;(void)blu2usb_ui_frame_set_text(f,r,0,t,tone);}if(learn){project_learn_pressed(ux,f);return;}const uint8_t pr=active_profile_row(ux);if(pr!=0u)set_row_tone(f,pr,BLU2USB_UI_TONE_CURRENT);if(ux->screen>=BLU2USB_SCREEN_LEFT_WILL_BECOME&&ux->screen<=BLU2USB_SCREEN_BACKWARD_WILL_BECOME){const uint8_t cr=(uint8_t)(1u+(unsigned)ux->custom_targets[ux->custom_source]);set_row_tone(f,cr,BLU2USB_UI_TONE_CURRENT);}const int selected=selected_row(ux);if(selected>=0&&selected<9)emphasize_row(f,(uint8_t)selected);for(unsigned c=0;c<BLU2USB_CONTROL_COUNT;++c){if(!blu2usb_interaction_is_pressed(&ux->interaction,(blu2usb_control_t)c))continue;for(uint8_t r=hint;r<9u;++r)if(row_has_control(s->rows[r],(blu2usb_control_t)c))emphasize_row(f,r);}}
uint16_t blu2usb_renderer_tone_rgb565(blu2usb_ui_tone_t tone){switch(tone){case BLU2USB_UI_TONE_TITLE:return BLU2USB_COLOR_MAGENTA;case BLU2USB_UI_TONE_STATIC:return BLU2USB_COLOR_OFF_WHITE_YELLOW;case BLU2USB_UI_TONE_ACTIONABLE:return BLU2USB_COLOR_LIGHT_GRAY;case BLU2USB_UI_TONE_EMPHASIZED:return BLU2USB_COLOR_WHITE;case BLU2USB_UI_TONE_CURRENT:return BLU2USB_COLOR_CYAN;default:return BLU2USB_COLOR_LIGHT_GRAY;}}
uint16_t blu2usb_renderer_background_rgb565(const blu2usb_ui_frame_t *f,uint8_t row){if(f==NULL)return BLU2USB_COLOR_BLACK;if(f->learn_background)return BLU2USB_COLOR_DARK_MAGENTA;return row>=f->hint_start_row?BLU2USB_COLOR_DARK_MAGENTA:BLU2USB_COLOR_BLACK;}
static uint16_t body_y(uint8_t r){const uint16_t first=(uint16_t)(8u+14u+17u);const uint16_t adv=26u;return(uint16_t)(first+(uint16_t)(r-1u)*adv);}
static uint16_t hint_y(uint8_t r){const uint16_t last=(uint16_t)(240u-12u-14u);const uint16_t adv=26u;return(uint16_t)(last-(uint16_t)(8u-r)*adv);}
uint16_t blu2usb_renderer_separator_boundary_y(const blu2usb_ui_frame_t *f){if(f==NULL||f->learn_background||f->hint_start_row==0u||f->hint_start_row>=9u)return 240u;const uint16_t y=hint_y(f->hint_start_row);return y<=11u?0u:(uint16_t)(y-11u);}
uint16_t blu2usb_renderer_text_y(const blu2usb_ui_frame_t *f,uint8_t r){if(r>=9u)return 240u;const uint16_t semantic=(uint16_t)(8u+(uint16_t)r*27u);if(f==NULL)return semantic;if(f->learn_background){if(r==0u)return 8u;return(uint16_t)(39u+(uint16_t)(r-1u)*25u);}if(r==0u||f->hint_start_row==0u||f->hint_start_row>9u)return semantic;const uint8_t sep=(uint8_t)(f->hint_start_row-1u);if(r>0u&&r<sep)return body_y(r);if(r>=f->hint_start_row)return hint_y(r);return semantic;}
static uint16_t cell_x(uint8_t c){return(uint16_t)(7u+(uint16_t)c*11u);}
static bool draw_cell(const blu2usb_display_hal_t *d,const blu2usb_ui_frame_t *f,uint8_t r,uint8_t c){const blu2usb_ui_cell_t *cell=&f->cells[r][c];if(cell->character==' ')return true;uint16_t pixels[140];const uint16_t fg=blu2usb_renderer_tone_rgb565(cell->tone),bg=blu2usb_renderer_background_rgb565(f,r);size_t out=0;for(uint8_t py=0;py<14u;++py){const uint8_t bits=glyph_row(cell->character,(uint8_t)(py/2u));for(uint8_t px=0;px<10u;++px){const uint8_t sx=(uint8_t)(px/2u);pixels[out++]=(bits&(uint8_t)(1u<<(4u-sx)))?fg:bg;}}return d->write_rgb565(d->context,cell_x(c),blu2usb_renderer_text_y(f,r),10u,14u,pixels);}
bool blu2usb_renderer_render(const blu2usb_display_hal_t *d,const blu2usb_ui_frame_t *f){if(d==NULL||f==NULL||d->fill_rect==NULL||d->write_rgb565==NULL)return false;if(f->learn_background){if(!d->fill_rect(d->context,0,0,240u,240u,BLU2USB_COLOR_DARK_MAGENTA))return false;}else{const uint16_t b=blu2usb_renderer_separator_boundary_y(f);if(b>0u&&!d->fill_rect(d->context,0,0,240u,b,BLU2USB_COLOR_BLACK))return false;if(b<240u&&!d->fill_rect(d->context,0,b,240u,(uint16_t)(240u-b),BLU2USB_COLOR_DARK_MAGENTA))return false;}for(uint8_t r=0;r<9u;++r)for(uint8_t c=0;c<21u;++c)if(!draw_cell(d,f,r,c))return false;return true;}
